tafsir_text:
وقوله :  {  وَلاَ تَتَبَدَّلُواْ الْخَبِيثَ بِالطَّيِّبِ .  .  .  }

يقول :  لا تأكلوا أموال اليتامى بدل أموالكم ،  وأموالهم عليكم حرام ،  وأموالكم حلال .

وقوله :  {  إِنَّهُ كَانَ حُوباً كَبِيراً } الحوب :  الإثم العظم .  ورأيت بنى أَسَد يقولون الحائب :  القاتل ،  وقد حاب يحوب .  وقرأ الحسن ( إنه كان حَوْبا كبيرا )

وقوله :  {  وَلاَ تُؤْتُواْ السُّفَهاء أَمْوَالَكُمُ .  .  .  }

السفهاء :  النساء والصبيان {  الَّتِي جَعَلَ اللَّهُ لَكُمْ قِيَاما } يقول التي بها تقومون قواما وقياما .  وقرأ نافع المدنى ( قِيَما ) والمعنى - والله أعلم - واحد .

والعرب تقول في جمع النساء ( اللاتى ) أكثر مما يقولون ( التي ) ،  ويقولون في جمع الأموال وسائر الأشياء سوى النساء ( التي ) أكثر مما يقولون فيه ( اللاتى ) .

وقوله :  {  وَاللاَّتِي يَأْتِينَ الْفَاحِشَةَ .  .  .  }

وفي قراءة عبد الله ( واللاتى يأتِين بالفاحشة ) والعرب تقول :  أتيت أمرا عظيما ،  وأتيت بأمر عظيم ،  وتكلمت كلاما قبيحا ،  وبكلام قبيح .  وقال في مريم {  لقد جِئتِ شيئا فرِيّا } و {  جِئتم شيئا إِدّا } ولو كانت فيه الباء لكان صوابا .

وقوله :  {  فأمسِكوهن في البيوتِ } كن يُحبَسن في بيوت لهن إذا أتين الفاحشة حتى أنزل الله تبارك وتعالى :  قولَه :  {  وَاللَّذَانَ يَأْتِيَانِها مِنكُمْ فَآذُوهُما .  .  .  }

فنسحَتْ هذه الأولى .

وقوله :  {  ثُمَّ يَتُوبُونَ مِن قَرِيبٍ .  .  .  }

يقول :  قبل الموت .  فمن تاب في صحَّته أو في مرضه قبل أن ينزل به الموت فتوبته مقبوله .

وقوله :  {  يَعْمَلُونَ السُّوءَ بِجَهالَةٍ } لا يجهلون أنه ذنب ،  ولكن لا يعلمون كُنْه ما فيه كعلم العالِم .

وقوله :  {  وَقَدْ أَفْضَى بَعْضُكُمْ إِلَى بَعْضٍ .  .  .  }

الإفضاء أن يخلو بها وإن لم يجامعها .

وقوله {  مِّيثَاقاً غَلِيظاً } الغليظ الذي أخذنه قوله تبارك وتعالى {  فإمساك بِمعروفٍ أو تسريحٌ بإحسان } .

وقوله :  {  لاَ تَقْرَبُواْ الصَّلاَةَ وَأَنْتُمْ سُكَارَى .  .  .  }

نزلت في نفر من أصحاب محمد صلى الله عليه وسلم شربوا وحضروا الصلاة مع رسول الله صلى الله عليه وسلم قبل تحريم الخمر .  فأنزل الله تبارك وتعالى {  لاَ تَقْرَبُواْ الصَّلاَةَ } مع رسول الله صلى الله عليه وسلم ،  ولكن صلّوها في رحالكم .

ثم قال {  وَلاَ جُنُباًً } أي لا تقربوها جُنُباً {  حَتَّى تَغْتَسِلُواْ }

ثم استثنى فقال {  إِلاَّ عَابِرِي سَبِيلٍ } يقول :  إلا أن تكونوا مسافرين لا تقدرون على الماء

ثم قال {  فَتَيَمَّمُواْ } والتيمم :  أن تقصد الصعيد الطيّب حيث كان .  وليس التيمم إلا ضربة للوجه وضربة لليدين للجنب وغير الجنب .

وقوله :  {  أَلَمْ تَرَ إِلَى الَّذِينَ يُزَكُّونَ أَنْفُسَهُمْ .  .  .  }

جاءت اليهود بأولادها إلى النبي صلى الله عليه وسلم فقالوا :  هل لهؤلاء ذنوب ؟  قال :  لا ،  قالوا :  فإنا مثلهم ما عملناه بالليل كفّر عنا بالنهار ،  وما عملناه بالنهار كفر عنا بالليل .  فذلك تزكيتهم أنفسهم .

وقوله :  {  وَلاَ يُظْلَمُونَ فَتِيلاً } الفتيل هو ما فتلت بين إصبعيك من الوسخ ،  ويقال :  وهو الذي في بطن النواة .

وقوله :  {  أَمْ يَحْسُدُونَ الناسَ على ما آتَاهُمُ اللَّهُ مِن فَضْلِهِ .  .  .  }

هذه اليهود حسدت النبي صلى الله عليه وسلم كثرة النساء ،  فقالوا :  هذا يزعم أنه نبي وليس له همّ إلا النساء .

فأنزل الله تبارك وتعالى {  فَقَدْ آتَيْنا آلَ إِبْرَاهِيمَ الْكِتَابَ وَالْحِكْمَةَ } وفي آل إبراهيم سليمان بن داود ،  وكان له تسعمائة امرأة ،  ولداود مائة امرأة .

فلما تليت عليهم هذه الآية كذَّب بعضهم وصدَّق بعضهم .  وهو قوله :  {  فَمِنْهُمْ مَّنْ آمَنَ بِهِ .  .  .  }

وقوله :  {  وَما لَكُمْ لاَ تُقَاتِلُونَ فِي سَبِيلِ اللَّهِ وَالْمُسْتَضْعَفِينَ .  .  .  }

و( المستضعفين ) في موضع خفض .

وقوله :  {  الظَّالِمِ أَهْلُها } خفض ( الظالم ) لأنه نعت للأهل ،  فلما أعاد الأهل على القربة كان فعل ما أضيف إليها بمنزلة فعلها ؛  كما تقول :  مررت بالرجلِ الواسعةِ دارُه ،  وكما تقول :  مررت برجلٍ حَسَنةٍ عينُه .  وفي قراءة عبد الله :   " أخرجنا من القرية التي كانت ظالمة "  .  ومثله مما نسب الظلم إلى القرية وإنما الظلم لأهلها في غير موضع من التنزيل .  من ذلك {  وكَمْ مِن قَرْيةٍ أهلكناها } ومنه قوله :  {  واسألِ القرية التي كنا فِيها } معناه :  سل أهل القرية .

وقوله :  {  فِي بُرُوجٍ مُّشَيَّدَةٍ .  .  .  }

يشدّد ما كان من جمع ؛  مثل قولك :  مررت بثياب مُصَبَّغةٍ وأكبشٍ مذبّحةٍ .  فجاز التشديد لأن الفعل متفرق في جمع .  فإذا أفردت الواحد من ذلك فإن كان الفعل يتردّد في الواحد ويكثر جاز فيه التشديد والتخفيف ؛  مثل قولك :  مررت برجل مشجّج ،  وبثوب ممزّق ؛  جاز التشديد ؛  لأن الفعل قد تردد فيه وكثر .  وتقول :  مررت بكبشٍ مذبوح ،  ولا تقل مذبح لأن الذبح لا يتردّد كتردّد التخرق ،  وقوله :  {  وبِئرٍ مُعَطَّلةٍ وقصرٍ مَشِيد } يجوز فيه التشديد ؛  لأن التشييد بناء فهو يتطاول ويتردّد .  يقاس على هذا ما ورد .

وقوله :  {  وَإِن تُصِبْهُمْ حَسَنَةٌ يَقُولُواْ هذه مِنْ عِندِ اللَّهِ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَقُولُواْ هذه مِنْ عِندِكَ .  .  .  }

وذلك أن اليهود لما أتاهم النبي صلى الله عليه وسلم بالمدينة قالوا :  ما رأينا رجلا أعظم شؤما من هذا ؛  نقصت ثمارنا وغلت أسعارنا .  فقال الله تبارك وتعالى :  إن أمطروا وأخصبوا قالوا :  هذه من عند الله ،  وإن غلت أسعارهم قالوا :  هذا من قِبل محمد ( صلى الله عليه وسلم ) .

وقول الله تبارك وتعالى :  {  قُلْ كُلٌّ مِّنْ عِندِ اللَّهِ } .

وقوله :  {  فَمالِ هؤلاء الْقَوْمِ } ( فمال ) كثرت في الكلام ،  حتى توهَّموا أن اللام متصلة ب ( ما ) وأنها حرف في بعضه .  ولاتصالِ القراءة لا يجوز الوقف على اللام ؛  لأنها لام خافضة .

وقوله :  {  طَاعَةٌ }

الرفع على قولك :  مِنا طاعة ،  أو أمرُك طاعة .  وكذلك {  قُل لاَ تُقْسِمُوا طَاعَةٌ مَّعْرُوفَةٌ } معناه - والله أعلم - :  قولوا :  سمع وطاعةٌ .  وكذلك التي في سورة محمد صلى الله عليه وسلم {  فأَولى لهم طاعةٌ وقولٌ معروف } ليست بمرتفعة ب ( لهم ) .  هي مرتفعة على الوجه الذي ذكرت لك .  وذلك أنهم أنزل عليهم الأمر بالقتال فقالوا :  سمع وطاعة ،  فإذا فارقوا محمدّا صلى الله عليه وسلم غيّروا قولهم .  فقال الله تبارك وتعالى {  فلو صدقوا الله لكان خيرا لهم } وقد يقول بعض النحويين :  وذكِر فيها القتال ،  وذكِرت ( طاعة ) وليست فيها واو فيجوزَ هذا الوجه .  ولو رددت الطاعة وجعلت كأنها تفسير للقتال جاز رفعها ونصبها ؛  أما النصب فعلى :  ذكر فيها القتال بالطاعة أو على الطاعة .  والرفع على :  ذكر فيها القتال ذكِر فيها طاعة .

وقوله :  {  بَيَّتَ طَائفَةٌ } القراءة أن تنصب التاء ،  لأنها على جهة فَعَل .  وفي قراءة عبد الله :   " بيّتَ مُبيّت منهم "  غير الذي تقول .  معناه :  غَيّروا ما قالوا وخالفوا .  وقد جزمها حمزة وقرأها بيَّتْ طائفة .  جزمها لكثرة الحركات ،  فلما سكنت التاء اندغمت في الطاء .

وقوله :  {  وَإِذَا جاءهم أَمْرٌ مِّنَ الأَمْنِ أَوِ الْخَوْفِ .  .  .  }

هذا نزل في سرايا كان رسول الله صلى الله عليه وسلم يبعثها ،  فإذا غَلَبوا أو غُلِبوا بادر المنافقون إلى الاستخبار عن حال السرايا ،  ثم أفشوه قبل أن يفشيه رسول الله صلى الله عليه وسلم أو يحدّثه ،  فقال {  أَذَاعُواْ بِهِ } يقول أفشوه .  ولو لم يفعلوا حتى يكون رسول الله صلى الله عليه وسلم الذي يخبر به لكان خيرا لهم ،  أو ردّوه إلى أمراء السرايا .  فذلك قوله {  وَلَوْ رَدُّوهُ إِلَى الرَّسُولِ وَإِلَى أُوْلِي الأَمْرِ مِنْهُمْ لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ } .

وقوله :  {  لاَتَّبَعْتُمُ الشَّيْطَانَ إِلاَّ قَلِيلاً } قال المفسرون معناه :  لعلمه الذين يستنبطونه إِلا قليلا .  ويقال :  أذاعوا به إلا قليلا .  وهو أجود الوجهين ؛  لأن علم السرايا إذا ظهر علمه المستنبط وغيره ،  والإذاعة قد تكن في بعضهم دون بعض .  فلذلك استحسنت الاستثناء من الإذاعة .

وقوله :  {  يَكُنْ لَّهُ كِفْلٌ مِّنْها .  .  .  }

الكِفل :  الحظّ .  ومنه قوله :  {  يؤتِكم كِفْلَيْنِ مِن رحمتِهِ } معناه :  نصيبين .

وقوله :  {  وَكَانَ اللَّهُ على كُلِّ شَيْءٍ مُّقِيتاً } المقِيْت :  المقدّر والمقتدر ،  كالذي يعطى كل رجل قُوته .  وجاء في الحديث :  كفي بالمرء ( إثما ) أن يضيع من يُقِيت ،  ويقوت .

وقوله :  {  إِلاَّ الَّذِينَ يَصِلُونَ إِلَى قَوْمٍ بَيْنَكُمْ وَبَيْنَهُمْ مِّيثَاقٌ .  .  .  }

يقول :  إذا واثق القوم النبي صلى الله عليه وسلم ألاّ يقاتلوه ولا يعينوا عليه ،  فكتبوا صلحا لم يحلّ قتالهم ولا من اتَّصل بهم ،  فكان رأيه في قتال رسول الله صلى الله عليه وسلم كرأيهم فلا يحلّ قتاله .  فذلك قوله ( يصلون ) معناه :  يتصلون بهم .

وقوله :  {  أَوْ جَاءوكُمْ حَصِرَتْ صُدُورُهُمْ } ،  يقول :  ضاقت صدورهم عن قتالكم أو قتال قومهم .  فذلك معنى قوله {  حَصِرَتْ صُدُورُهُمْ } أي ضاقت صدورهم .  وقد قرأ الحسن  " حصِرةً صدورهم "  ،  والعرب تقول :  أتانى ذهب عقلُه ،  يريدون قد ذهب عقله .  وسَمع الكسائي بعضهم يقول :  فأصبحتُ نظرت إلى ذات التنانِيرِ .  فإذا رأيت ( فَعَل  ) بعد ( كان  ) ففيها ( قد  )مضمرة ،  إلا أن يكون مع كان جحد فلا تضمر فيها ( قد مع جحد ) لأنها توكيد والجحد لا يؤكَّد ؛  ألا ترى أنك تقول :  ما ذهبت ،  ولا يجوز ما قد ذهبت .

وقوله :  {  فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ }

مرفوع على قولك :  فعليه تحرير رقبة .  والمؤمنة :  المصلِّية المدرِكة .  فإن لم يقل :  رقبة مؤمنة ،  أجزأت الصغيرة التي لم تصلِّ ولم تبلغ .

وقوله :  {  فَإِن كَانَ مِن قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ } كان الرجل يسلم في قومه وهم كفّار فيكتم إسلامه .  فمن قُتِل وهو غير معلوم إسلامه من هؤلاء أعتق قاتله رقبة ولم تدفع دِيته إلى الكفار فيقْوَوْا بها على أهل الإسلام .  وذلك إذا لم يكن بين قومه وبين النبي صلى الله عليه وسلم عهد .  فإن كان عهد جرى مجرى المسلم .

وقوله :  {  يَا أَيُّها الَّذِينَ آمَنُواْ إِذَا ضَرَبْتُمْ فِي سَبِيلِ اللَّهِ فَتَبَيَّنُواْ .  .  .  }

( فَتَثَبَّتُوا - قراءة عبد الله بن مسعود وأصحابه .  وكذلك التي في الحجُرات .  ويَقْرأ أن :  فَتَثَبَّتُوا ) وهما متقاربتان في المعنى .  تقول للرجل :  لا تعجل بإقامة حتى تتبين وتتثبت .

وقوله :  {  وَلاَ تَقُولُواْ لِمَنْ أَلْقَى إِلَيْكُمُ السَّلاَمَ لَسْتَ مُؤْمِنا } ذكروا أنه رجل سلّم على بعض سرايا المسلمين ،  فظنّوا أنه عائذ بالإسلام وليس بمسلم فقُتِل .  وقرأه العامة :  السَلَم .  والسلم :  الاستسلام والإعطاء بيده .

وقوله :  {  فَلْتَقُمْ .  .  .  }

وكلّ لام أمر إذا استؤنفت ولم يكن قبلها واو ولا فاء ولا ثُمَّ كُسرت .  فإذا كان معها شيء من هذه الحروف سُكّنت .  وقد تكسر مع الواو على الأصل .  وإنما تخفيفها مع الواو كتخفيفهم ( وهْوَ ) قال ذاك ،  ( وهي ) قالت ذاك .  وبنو سُلَيم يفتحون اللام إذا استؤنفت فيقولون :  لَيَقم زيد ،  ويجعلون اللام منصوبة في كل جهة ؛  كما نصَبت تميم لام كى إذا قالوا :  جئت لآَخذ حقّى .

وقوله :  {  طَائفَةٌ أُخْرَى } ولم يقل :  آخرون ؛  ثم قال {  لَمْ يُصَلُّواْ } ولم يقل :  فلتصل .  ولو قيل :   " فلتُصل "  كما قيل  " أخرى "  لجاز ذلك .  وقال في موضع آخر :  {  وإنْ طائفتانِ مِن المؤمِنِين اقتتلوا } ولو قيل :  اقتتلتا في الكلام كان صوابا .  وكذلك قوله {  هذانِ خَصْمانِ اختصموا في ربِّهم } ولم يقل :  اختصما .  وقال {  فِريقا هدى وفرِيقا حَقَّ عليهم الضّلالة } وفي قراءة أبىّ  " عليه الضلالة "  .  فإذا ذكرت اسما مذكّرا لجمع جاز جمع فعله وتوحيده ؛  كقول الله تعالى {  وإنا لجميع حاذرون } .  وقوله :  {  أم يقولون نَحْن جَميعٌ مُنْتَصر } وكذلك إذا كان الاسم مؤنّثا وهو لجمع جعلت فعله كفعل الواحدة الأنثى الطائفة والعصبة والرفقة .  وإن شئت جمعته فذكَّرته على المعنى .  كلّ ذلك قد أتى في القرآن .

وقوله :  {  لَهَمَّتْ طَّائفَةٌ .  .  .  }

يريد :  لقد همت طائفة فأضمرت .

وقوله :  {  أَن يُضِلُّوكَ } :  يُخطِّئوك في حكمك .

وقوله :  {  إِن يَدْعُونَ مِن دُونِهِ إِلاَّ إِناثاً .  .  .  }

يقول :  اللات والعُزَّى وأشباههما من الآلهة المؤنثة .  وقد قرأ ابن عباس {  إِن يَدْعُونَ مِن دُونِهِ إِلاَّ إِناثاً } جمع الوثن فضم الواو فهمزها ،  كما قال {  وإذا الرُّسُلُ أُقِّتَت } وقد قرئت {  إنْ يَدْعُونَ مِن دُونِه إلا أُنُثا } جمع الإناث ،  فيكون مثل جمع الثمار والثمر {  كُلُوا مِنْ ثُمُرِه } .

وقوله :  {  نَصِيباً مَّفْرُوضاً .  .  .  }

جعل الله له عليه السبيل ؛  فهو كالمفروض .

وقوله :  {  قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ وَما يُتْلَى .  .  .  }

( معناه :  قل الله يفتيكم فيهنّ وما يتلى ) .  فموضع ( ما ) رفع كأنه قال :  يفتيكم فيهنّ ما يتلى عليكم .  وإن شئت جعلت ما في موضع خفض :  يفتيكم الله فيهنّ وما يتلى عليكم غيرهنّ .

وقوله :  {  وَالْمُسْتَضْعَفِينَ } في موضع خفض ،  على قوله :  يفتيكم فيهنّ وفي المستضعفين .  وقوله :  {  وَأَن تَقُومُواْ } ( أن ) موضع خفض على قوله :  ويفتيكم في أن تقوموا لليتامى بالقسط .

وقوله :  {  خَافَتْ مِن بَعْلِها نُشُوزاً .  .  .  }

والنشوز يكون من قِبل المرأة والرجل .  والنشوز هاهنا من الرجل لا من المرأة .  ونشوزه أن تكون تحته المرأة الكبيرة فيريد أن يتزوج عليها شابّة فيؤثرها في القسمة والجماع .  فينبغي له أن يقول للكبيرة :  إني أريد أن أتزوّج عليك شابَّة وأوثرها عليك ،  فإن هي رضيت صلح ذلك له ،  وإن لم ترض فلها من القسمة ما للشابّة .

وقوله :  {  وَأُحْضِرَتِ الأنْفُسُ الشُّحَّ } إنما عنى به الرجل وامرأته الكبيرة .  ضنّ الرجل بنصيبه من الشابة ،  وضنّت الكبيرة بنصيبها منه .  ثم قال :  وإن رضيت بالإمرة .

وقوله :  {  كُونُواْ قَوَّامِينَ بِالْقِسْطِ شُهَدَاء للَّهِ .  .  .  }

هذا في إقامة الشهادة على أنفسهم وعلى الوالدين والأقربين .  ولا تنظروا في غِنى الغنِىّ ولا فقر الفقير ؛  فإن الله أولى بذلك .

( فلا تَتَّبِعُوا الهوى [ أن تعدِلوا ] ) فرارا من إقامة الشهادة .  وقد يقال :  لا تتبعوا الهوى لتعدلوا ؛  كما تَقول :  لا تتبِعنّ هواك لتُرضِى ربك ،  أي إني أنهاك عن هذا كيما ترضِى ربك .  وقوله {  وَإِن تَلْوُواْ } وتَلُوا ،  قد قرئتا جميعا .  ونرى الذين قالوا ( تلوا ) أرادوا ( تَلْؤُوا ) فيهمزون الواو لانضمامها ،  ثم يتركون الهمز فيتحوّل إعراب الهمز إلى اللام فتسقط الهمزة .  إلا أن يكون المعنى فيها :  وإن تلوا ذلك ،  يريد :  تتولَّوه {  أَوْ تُعْرِضُواْ } عنه :  أو تتركوه ،  فهو وجه .

وقوله :  {  إِنَّ الَّذِينَ آمَنُواْ ثُمَّ كَفَرُواْ ثُمَّ آمَنُواْ ثُمَّ كَفَرُواْ .  .  .  }

وهم الذين آمنوا بموسى ثم كفرا من بعده بعُزَيْر ،  ثم آمنوا بعُزَيْر وكفروا بعيسى .  وآمنت اليهود بموسى وكفرت بعيسى .

ثم قال :  {  [ ثُمَّ ] ازْدَادُواْ كُفْراً } يعنى اليهود :  ازدادوا كفرا بكفرهم بمحمد صلى الله عليه وسلم .

وقوله :  {  وَما قَتَلُوهُ وَما صَلَبُوهُ .  .  .  }

الهاء ها هنا لعيسى صلى الله عليه وسلم .

وقوله {  وَما قَتَلُوهُ يَقِينا } الهاء ها هنا للعلم ،  كما تقول قتلته علما ،  وقتلته يقينا ،  للرأي والحديث والظنّ .

وقوله :  {  وَلاَ تَقُولُواْ ثَلاَثَةٌ .  .  .  }

أي تقولوا :  هم ثلاثة ؛  كقوله تعالى {  سيقولون ثلاثَةٌ رابعهم } فكل ما رأيته بعد القول مرفوعا ولا رافع معه ففيه إضمار اسم رافع لذلك الاسم .

وقوله :  {  سُبْحانَهُ أَن يَكُونَ لَهُ وَلَدٌ } يصلح في ( أن ) مِن وعن ،  فإذا أُلقيتا كانت ( أن ) في موضع نصب .  وكان الكسائي يقول :  هي في موضع خفض ،  في كثير من أشباهها .
